using System;
using System.Drawing;
using System.IO;
using System.Linq;
using System.Windows.Forms;
namespace Synkoz {
 public static class TimelineR3 {
  public static void Draw(Graphics g,Font font,Montage m,Rectangle area,TrackFx936 fx){var music=new Music936(m);double scale=area.Width/Math.Max(.001,m.Duration);if(fx.UseZones)foreach(var zone in fx.Zones){using(var brush=new SolidBrush(Color.FromArgb(65,Color.LimeGreen)))g.FillRectangle(brush,area.X+(float)(zone.Start*scale),area.Y,(float)((zone.End-zone.Start)*scale),area.Height);}
   if(!music.Available)return;double last=music.Beat(m.Duration)/4;int step=Math.Max(1,(int)Math.Ceiling(last/Math.Max(1,area.Width/55)));for(int bar=0;bar<=last;bar+=step){float x=area.X+(float)(music.Time(bar*4)*scale);g.DrawLine(Pens.Gray,x,area.Y,x,area.Bottom);g.DrawString((bar+1).ToString(),font,Brushes.White,x+2,area.Y+2);}
  }
 }
 public sealed class ZonesFormR3:Form {
  public ZonesFormR3(Montage m,TrackFx936 target){Text="Zones d’activation FX — aucun média découpé";UiR2.Fit(this,920,530);var draft=UiR2.Copy(target);var music=new Music936(m);var canvas=new ZoneCanvasR3(m,draft){Dock=DockStyle.Top,Height=180};Controls.Add(canvas);var list=new ListBox{FormattingEnabled=true,Dock=DockStyle.Fill};Controls.Add(list);list.BringToFront();var tools=new FlowLayoutPanel{Dock=DockStyle.Bottom,Height=100,AutoScroll=true};Controls.Add(tools);var active=new CheckBox{Text="Limiter les FX aux zones vertes",Checked=draft.UseZones,AutoSize=true};active.CheckedChanged+=delegate{draft.UseZones=active.Checked;canvas.Invalidate();};tools.Controls.Add(active);
   double max=music.Available?Math.Max(1,1+music.Beat(m.Duration)/4):Math.Max(1,m.Duration);var start=UiR2.Number(music.Available?1:0,music.Available?1:0,(decimal)max,3);var end=UiR2.Number(max,music.Available?1:0,(decimal)max,3);start.Width=end.Width=90;tools.Controls.Add(new Label{Text=music.Available?"Départ / fin (mesures)":"Départ / fin (secondes)",AutoSize=true});tools.Controls.Add(start);tools.Controls.Add(end);
   Action refresh=()=>{list.Items.Clear();foreach(var z in draft.Zones)list.Items.Add(music.Available?(1+music.Beat(z.Start)/4).ToString("F3")+" → "+(1+music.Beat(z.End)/4).ToString("F3"):z.Start.ToString("F3")+" → "+z.End.ToString("F3"));canvas.Invalidate();};
   Action<double,double> add=(a,b)=>{a=Math.Max(0,a);b=Math.Min(m.Duration,b);if(b<=a)return;draft.Zones.Add(new ZoneR3{Start=a,End=b});draft.Zones=draft.Zones.OrderBy(z=>z.Start).ToList();active.Checked=true;refresh();};canvas.Selected=add;
   var insert=new Button{Text="Ajouter zone",AutoSize=true};insert.Click+=delegate{add(music.Available?music.Time(((double)start.Value-1)*4):(double)start.Value,music.Available?music.Time(((double)end.Value-1)*4):(double)end.Value);};tools.Controls.Add(insert);
   var split=new Button{Text="Couper au départ",AutoSize=true};split.Click+=delegate{double t=music.Available?music.Time(((double)start.Value-1)*4):(double)start.Value;var z=draft.Zones.FirstOrDefault(x=>t>x.Start&&t<x.End);if(z!=null){double old=z.End;z.End=t;draft.Zones.Add(new ZoneR3{Start=t,End=old});draft.Zones=draft.Zones.OrderBy(x=>x.Start).ToList();refresh();}};tools.Controls.Add(split);
   var remove=new Button{Text="Retirer zone",AutoSize=true};remove.Click+=delegate{int i=list.SelectedIndex;if(i>=0){draft.Zones.RemoveAt(i);refresh();}};tools.Controls.Add(remove);var save=new Button{Text="Valider",AutoSize=true};save.Click+=delegate{target.UseZones=draft.UseZones;target.Zones=draft.Zones;DialogResult=DialogResult.OK;};tools.Controls.Add(save);tools.Controls.Add(new Label{Text="Glisser sur la timeline pour créer une zone (cran : 1 temps). Hors zone, tous les FX sont immédiatement neutres.",AutoSize=true});refresh();
  }
  sealed class ZoneCanvasR3:Control {readonly Montage m;readonly TrackFx936 fx;int down=-1;public Action<double,double> Selected;public ZoneCanvasR3(Montage model,TrackFx936 effects){m=model;fx=effects;DoubleBuffered=true;BackColor=Color.FromArgb(35,39,49);}protected override void OnPaint(PaintEventArgs e){base.OnPaint(e);TimelineR3.Draw(e.Graphics,Font,m,ClientRectangle,fx);}protected override void OnMouseDown(MouseEventArgs e){base.OnMouseDown(e);down=e.X;Capture=true;}protected override void OnMouseUp(MouseEventArgs e){base.OnMouseUp(e);if(down<0)return;double a=Math.Min(down,e.X)*m.Duration/Math.Max(1,Width),b=Math.Max(down,e.X)*m.Duration/Math.Max(1,Width);var clock=new Music936(m);if(clock.Available){a=clock.Time(Math.Round(clock.Beat(a)));b=clock.Time(Math.Round(clock.Beat(b)));}down=-1;Capture=false;if(Selected!=null)Selected(a,b);}}
 }
 public sealed partial class MontagePanel {
  void AddToolsR3(FlowLayoutPanel bar){bar.Height=155;InitController940(bar);Action<string,Action> button=(title,action)=>{var b=new Button{Text=title,AutoSize=true};b.Click+=delegate{try{if(occupied())throw new Exception("Terminer la prise avant de modifier le montage.");action();}catch(Exception ex){status.Text=ex.Message;}};bar.Controls.Add(b);};
   button("Latence",()=>{if(Current==null)throw new Exception("Ouvrir un montage.");using(var f=new CalibrationR5(Current))f.ShowDialog(FindForm());Render();});
   button("Ouvrir projet",()=>{using(var d=new OpenFileDialog{InitialDirectory=FoldersR2.Get("project"),Filter="Projet Snkoz|*.snkozproject"})if(d.ShowDialog()==DialogResult.OK){ShowMontage(FilesR3.LoadProject(d.FileName));FoldersR2.Set("project",Path.GetDirectoryName(d.FileName));}});
   button("Sauver projet…",()=>{if(Current==null)throw new Exception("Ouvrir un montage.");using(var d=new SaveFileDialog{InitialDirectory=FoldersR2.Get("project"),Filter="Projet Snkoz|*.snkozproject",FileName="Projet.snkozproject"})if(d.ShowDialog()==DialogResult.OK){FilesR3.SaveProject(Current,d.FileName);FoldersR2.Set("project",Path.GetDirectoryName(d.FileName));status.Text="Projet enregistré : références aux médias et tous les réglages.";}});
   button("+ Piste transparente",()=>{if(Current==null){string folder=Path.Combine(Preferences936.Load().DefaultTakeFolder,"Graphique_"+DateTime.Now.ToString("yyyyMMdd_HHmmss"));Directory.CreateDirectory(folder);Current=new Montage{Folder=folder,Duration=8};Current.Beats.Add(new Beat936{Time=0,Beat=0});Current.Beats.Add(new Beat936{Time=8,Beat=16});}
    using(var f=new GraphicFormR3(Current.Duration)){if(f.ShowDialog(FindForm())!=DialogResult.OK)return;Current.Duration=Math.Max(Current.Duration,f.Duration);Current.Tracks.Add(new Track{ShortName=f.TrackName,Video=new Device{Name="Piste transparente",Video=true},Fx=new TrackFx936{Graphic=true,CanvasWidth=f.WidthPixels,CanvasHeight=f.HeightPixels}});Current.Blocks.Add(new MediaBlock{Track=Current.Tracks.Count-1,Start=0,Duration=Current.Duration,File="",Video=true});Current.Save();Render();}});
   button("Audio preview",()=>{if(Current==null)throw new Exception("Ouvrir un montage.");if(Current.PreviewAudio939==null)Current.PreviewAudio939=new TrackFx936();using(var f=new PreviewAudioR3(Current,0,Current.PreviewAudio939))if(f.ShowDialog(FindForm())==DialogResult.OK)Current.Save();});
   button("Qualité preview",()=>{if(Current==null)throw new Exception("Ouvrir un montage.");using(var f=new RangeFormR3(Current,false))f.ShowDialog(FindForm());});
  }
 }
 public sealed class GraphicFormR3:Form {
  public int WidthPixels,HeightPixels;public double Duration;public string TrackName;
  public GraphicFormR3(double duration){Text="Nouvelle piste transparente";ClientSize=new Size(430,260);StartPosition=FormStartPosition.CenterParent;var name=new TextBox{Text="Animations",Location=new Point(170,20),Width=220};var w=UiR2.Number(1920,16,7680,0);w.Location=new Point(170,60);var h=UiR2.Number(1080,16,7680,0);h.Location=new Point(170,100);var d=UiR2.Number(duration,1,86400,3);d.Location=new Point(170,140);Controls.AddRange(new Control[]{name,w,h,d,new Label{Text="Nom",Location=new Point(15,24)},new Label{Text="Largeur (pixels)",Location=new Point(15,64),Width=150},new Label{Text="Hauteur (pixels)",Location=new Point(15,104),Width=150},new Label{Text="Durée projet (s)",Location=new Point(15,144),Width=150}});var ok=new Button{Text="Créer",Location=new Point(280,210)};ok.Click+=delegate{WidthPixels=(int)w.Value;HeightPixels=(int)h.Value;Duration=(double)d.Value;TrackName=name.Text;DialogResult=DialogResult.OK;};Controls.Add(ok);Controls.Add(new Label{Text="Sans prise : repères initiaux à 120 BPM, 4/4.\nAvec prise : repères musicaux existants conservés.",Location=new Point(15,180),Size=new Size(400,32)});}
 }
}
